import json
import os

def extract_main():
    transcript_path = r"C:\Users\Ayaz Khan\.gemini\antigravity\brain\1c0124d7-e226-4149-8661-e78958016c4f\.system_generated\logs\transcript_full.jsonl"

    if not os.path.exists(transcript_path):
        print("Transcript not found.")
        return

    found_any = False

    with open(transcript_path, "r", encoding="utf-8") as f:
        for line_num, line in enumerate(f, 1):
            if "views/procedures/triggers" in line:
                print(f"Match found on line {line_num}")
                found_any = True
                with open(f"scratch/match_{line_num}.json", "w", encoding="utf-8") as out:
                    out.write(line)

    if not found_any:
        print("No match found in current transcript.")

if __name__ == "__main__":
    extract_main()
